import {biologyStages,freshBiology,addBiologyReactant,finishBiologyStage} from './life-biology-model.js';
import {bindReactantPickup} from './life-reactant-drag.js';
import {createFoodPlayback} from './food-playback.js';
const atom=(x,y,label,colour,r=15)=>`<g><circle cx="${x}" cy="${y}" r="${r}" fill="${colour}" stroke="#fff9"/><text x="${x}" y="${y+5}" text-anchor="middle" fill="white" font-size="13" font-weight="bold">${label}</text></g>`;
const water=(x,y)=>atom(x,y,'O','#bd7256')+atom(x-19,y-10,'H','#7d9e9e',10)+atom(x+19,y-10,'H','#7d9e9e',10);
const co2=(x,y)=>atom(x-25,y,'O','#bd7256')+atom(x,y,'C','#526b66')+atom(x+25,y,'O','#bd7256');
function biologyArt(key){const photo=key==='photo';return `<svg viewBox="0 0 760 370" role="img" aria-label="${photo?'葉綠體中的光反應與碳反應，追蹤水、氧氣、二氧化碳與糖':'有氧呼吸中養分氧化與氧氣還原的相連過程'}"><defs><radialGradient id="bio-body-${key}"><stop stop-color="${photo?'#e6edb9':'#f3e4c7'}"/><stop offset="1" stop-color="${photo?'#b3ca85':'#c9d9c2'}"/></radialGradient></defs>
<ellipse cx="385" cy="199" rx="319" ry="143" fill="url(#bio-body-${key})" stroke="#839c68" stroke-width="3"/><ellipse cx="385" cy="199" rx="308" ry="132" fill="none" stroke="#f7f8dc" stroke-width="3"/>
<text x="380" y="81" text-anchor="middle" font-size="16" fill="#436442" font-weight="bold">${photo?'葉綠體 · 放大示意':'細胞內 · 分段追蹤示意'}</text>
${photo?`<g fill="#87a75f" stroke="#658644">${[0,1,2,3].map(i=>`<ellipse cx="214" cy="${169+i*13}" rx="74" ry="14"/>`).join('')}</g><circle cx="82" cy="39" r="23" fill="#e9c06e"/><path d="M105 61L160 136" stroke="#cfaa59" stroke-width="3" stroke-dasharray="6 5"/><text x="81" y="13" text-anchor="middle" font-size="12" fill="#9b7934">光能</text>`:`<path d="M132 163C156 123 247 134 285 176S259 249 207 246S104 212 132 163Z" fill="#dca874" stroke="#a77753" stroke-width="2"/><path d="M149 180q15-35 30 0t30 0 30 0 30 0" fill="none" stroke="#fae1b2" stroke-width="6"/>`}
<circle cx="516" cy="199" r="67" fill="#f4f3d477" stroke="#89a370" stroke-width="3" stroke-dasharray="7 5"/>
<path d="M471 156Q527 127 567 182M565 168l4 17-17-3M559 239Q508 273 465 219M466 233l-3-17 17 2" fill="none" stroke="#6e905e" stroke-width="3"/>
<text x="210" y="113" text-anchor="middle" font-size="14" fill="#4c6d48">① ${photo?'光反應 · 水裂解':'養分分解 · 失去電子'}</text><text x="516" y="113" text-anchor="middle" font-size="14" fill="#4c6d48">② ${photo?'碳反應':'電子傳遞鏈末端'}</text>
<g data-bio-carrier opacity="0"><path d="M274 259Q368 315 452 260" fill="none" stroke="#b19755" stroke-width="3" stroke-dasharray="5 5"/><rect x="272" y="287" width="231" height="29" rx="14" fill="#fbf2ce" stroke="#c5b879"/><text x="388" y="306" text-anchor="middle" fill="#8b743b" font-size="12">${photo?'ATP、NADPH：帶來能量與還原力':'電子攜帶者：把電子接續傳下去'}</text></g>
<g data-bio-input-one>${photo?water(35,200)+water(35,238):`<path d="M35 171l27 16v31l-27 16-27-16v-31Z" fill="#d9b56b" stroke="#a98b4c"/><text x="35" y="206" text-anchor="middle" font-size="12" fill="#655328">葡萄糖</text>`}</g>
<g data-bio-oxygen-out opacity="0">${photo?atom(230,120,'O','#bd7256')+atom(255,120,'O','#bd7256'):co2(242,120)}<text x="242" y="149" text-anchor="middle" font-size="12" fill="#537358">${photo?'O₂ 排出':'CO₂ 釋出'}</text></g>
<g data-bio-hydrogen opacity="0"><text x="220" y="233" text-anchor="middle" font-size="13" fill="#486b6b">${photo?'H⁺ ＋ e⁻':'電子交給攜帶者'}</text></g>
<g data-bio-input-two opacity="0">${photo?co2(735,204):atom(722,204,'O','#bd7256')+atom(747,204,'O','#bd7256')}</g>
<g data-bio-intermediate opacity="0"><rect x="468" y="174" width="96" height="50" rx="10" fill="#fff8de" stroke="#aeb97d"/><text x="516" y="196" text-anchor="middle" font-size="13" fill="#557349">${photo?'三碳糖':'O₂ 接受電子'}</text><text x="516" y="213" text-anchor="middle" font-size="11" fill="#81915d">${photo?'G3P':'＋ H⁺'}</text></g>
<g data-bio-product opacity="0">${photo?`<path d="M654 262l29 17v32l-29 17-29-17v-32Z" fill="#e0ba71" stroke="#b29150"/><text x="654" y="297" text-anchor="middle" font-size="12" fill="#5c512c">葡萄糖</text>`:water(646,294)+`<text x="646" y="328" text-anchor="middle" font-size="12" fill="#456a69">水 H₂O</text>`}<path d="M565 236L614 270" stroke="#a39458" stroke-width="2" fill="none"/></g>
<text x="380" y="357" text-anchor="middle" fill="#708365" font-size="11">${photo?'先追水的去向，再追碳的去向；實際兩階段相互配合':'實際反應分布於細胞質與粒線體，圖中合併呈現'}</text></svg>`;}
export function biologyMarkup(key,complete=false){const photo=key==='photo',steps=biologyStages[key];return `<section class="life-paired-reaction life-biology-lab" data-glossary-skip data-life-observation data-life-reaction="${key}" data-phase="${complete?'complete':'ready'}" data-bio-step="${complete?2:0}"><div class="reaction-heading"><div><small>親手加入 · 分段追蹤</small><h4>${photo?'光合作用：先追水，再追碳':'有氧呼吸：追蹤養分與氧氣'}</h4></div><button type="button" class="text-button" data-life-retry>↺ 重新取用</button></div><p class="life-mix-instruction">${photo?'先加入水，看水裂解、氧氣排出；再加入二氧化碳，觀察碳反應。':'先追葡萄糖分解，再追氧氣接受電子；把兩邊的變化連起來。'}<span>拖進圖中的反應區；也可以先點反應物，再點反應區。</span></p>
<div class="bio-stage-steps">${steps.map((s,i)=>`<span data-bio-step-label="${i}">${i+1}　${s.name}</span>`).join('')}</div>
<div class="life-mix-workbench"><div class="life-reactant-rack"><small>依序拿取反應物</small>${steps.map((s,i)=>`<button type="button" class="life-reactant" data-life-input="${s.id}" aria-label="拿取${s.label}" aria-pressed="false"><span class="bio-supply-icon">${photo?(i===0?'H₂O':'CO₂'):(i===0?'C₆H₁₂O₆':'O₂')}</span><strong>${s.label}</strong><span data-input-state>${i?'等前一步完成':'拿取 →'}</span></button>`).join('')}</div><div class="life-reactor-panel"><div class="life-reactor-condition">${photo?'陽光與葉綠素參與 · 葉片內的葉綠體':'有氧條件 · 各階段以電子攜帶者連接'}</div><div class="bio-stage-art">${biologyArt(key)}<button type="button" data-life-drop class="bio-stage-drop" aria-label="放入選取的反應物"><span data-life-drop-hint>水放入這裡</span></button></div><div class="life-mix-slots"><b data-life-mix-count>0 / 2 段</b><span data-bio-next></span></div></div></div>
<p class="life-observe-status" data-life-animation-status role="status"></p><div class="life-manual-results"><div class="life-result-path oxidation" data-bio-result="0"><b>${photo?'水 → 氧氣':'葡萄糖 → 二氧化碳'}</b><p><strong data-life-pair-label>${photo?'水被氧化':'葡萄糖被氧化'}</strong><small>失去電子</small></p></div><div class="life-result-path reduction" data-bio-result="1"><b>${photo?'二氧化碳 → 養分':'氧氣 → 水'}</b><p><strong data-life-pair-label>${photo?'二氧化碳被還原':'氧氣被還原'}</strong><small>得到電子</small></p></div></div>
<div class="life-paired-equation"><small>多步反應的總反應式</small><b>${photo?'6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂':'C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O ＋ 能量'}</b></div><p class="life-pair-model">分段是為了追蹤物質，不表示氧化與還原可以單獨發生。${photo?'光反應中水被氧化，NADP⁺ 等接受電子；碳反應再利用 NADPH 的還原力。碳反應先產生三碳糖，再用於合成葡萄糖等養分。':'有氧呼吸各段彼此銜接，O₂ 是電子傳遞鏈的末端電子接受者；圖示不是在無氧下先完成全部氧化。'} 圖卡代表一批物質，球數、位置與時間簡化；不代表數量或實際路徑。</p></section>`;}
export function bindBiologyLab(scene,onComplete){const key=scene.dataset.lifeReaction,steps=biologyStages[key],zone=scene.querySelector('[data-life-drop]'),status=scene.querySelector('[data-life-animation-status]'),retry=scene.querySelector('[data-life-retry]');let state=freshBiology(key,scene.dataset.phase==='complete'),selected=null,playback=null,alive=true;const disposers=[],progress=[state.step>0?1:0,state.step>1?1:0];
const usable=()=>alive&&!scene.closest('[inert]');
function paint(){const [a,b]=progress,show=(selector,opacity,transform)=>{const el=scene.querySelector(selector);el.setAttribute('opacity',String(Math.max(0,Math.min(1,opacity))));if(transform)el.setAttribute('transform',transform);};
show('[data-bio-input-one]',1-Math.max(0,(a-.3)/.3),`translate(${Math.min(a/.35,1)*180} 0)`);show('[data-bio-oxygen-out]',(a-.38)*4,`translate(0 ${-Math.max(0,(a-.6)/.4)*92})`);show('[data-bio-hydrogen]',(a-.4)*4);show('[data-bio-carrier]',(a-.5)*3);show('[data-bio-input-two]',b>0&&b<.6?1:0,`translate(${-Math.min(b/.5,1)*219} 0)`);show('[data-bio-intermediate]',b<.78?(b-.35)*5:1-(b-.78)/.22);show('[data-bio-product]',(b-.7)/.3,`translate(${-25*(1-b)} 0)`);
scene.querySelectorAll('[data-bio-result]').forEach((el,i)=>{const done=progress[i]>=.45;el.classList.toggle('revealed',done);el.setAttribute('aria-hidden',String(!done));});}
function refresh(){scene.dataset.phase=state.phase;scene.dataset.bioStep=String(state.step);scene.querySelectorAll('[data-life-input]').forEach((el,i)=>{const active=state.phase==='ready'&&i===state.step;el.disabled=!active;el.setAttribute('aria-pressed',String(selected===el.dataset.lifeInput));el.querySelector('[data-input-state]').textContent=i<state.step?'✓ 已觀察':state.phase==='running'&&i===state.step?'反應進行中…':active?(selected?'已拿取 · 放入 →':'拿取 →'):'等前一步完成';});scene.querySelectorAll('[data-bio-step-label]').forEach((el,i)=>el.classList.toggle('active',i===state.step||state.step===2));zone.disabled=state.phase!=='ready';zone.classList.toggle('life-item-selected',!!selected);scene.querySelector('[data-life-drop-hint]').textContent=state.phase==='complete'?'✓ 兩段觀察完成':state.phase==='running'?'反應進行中…':steps[state.step].label+' 放入這裡 ↓';scene.querySelector('[data-life-mix-count]').textContent=state.step+' / 2 段';scene.querySelector('[data-bio-next]').textContent=state.step<2?steps[state.step].name:'兩邊一起理解';paint();}
const visible=()=>{const r=scene.getBoundingClientRect();playback?.setActive(alive&&state.phase==='running'&&!document.hidden&&!document.querySelector('dialog[open]')&&r.bottom>0&&r.top<innerHeight);};
const add=id=>{if(!usable()||!addBiologyReactant(state,id))return;selected=null;const n=state.step;refresh();status.textContent=steps[n].running;playback=createFoodPlayback({duration:matchMedia('(prefers-reduced-motion:reduce)').matches?1:5200,onTime:t=>{progress[n]=t/4;paint();},onState:s=>{if(!alive||!s.complete||!finishBiologyStage(state))return;refresh();status.textContent=steps[n].done;if(state.phase==='complete')onComplete();else scene.querySelector('[data-life-input="'+steps[state.step].id+'"]')?.focus({preventScroll:true});}});visible();};
for(const el of scene.querySelectorAll('[data-life-input]'))disposers.push(bindReactantPickup(el,zone,{disabled:()=>!usable()||el.disabled,onSelect:()=>{selected=el.dataset.lifeInput;refresh();status.textContent='已拿取，放進圖中的反應區。';},onDrop:()=>add(el.dataset.lifeInput),onMiss:()=>{selected=null;refresh();status.textContent='還沒進入反應區，請再放一次。';},onCancel:()=>{selected=null;refresh();status.textContent='已放回，可以重新拿取。';}}));
zone.onclick=()=>{if(selected)add(selected);else if(usable())status.textContent=steps[state.step]?.instruction||'';};retry.onclick=()=>{if(!usable())return;playback?.dispose();playback=null;state=freshBiology(key);progress.fill(0);selected=null;refresh();status.textContent=steps[0].instruction;};refresh();status.textContent=state.phase==='complete'?steps[1].done:steps[0].instruction;
window.addEventListener('scroll',visible,{passive:true,capture:true});window.addEventListener('resize',visible);document.addEventListener('visibilitychange',visible);const observer=new MutationObserver(visible);observer.observe(document.body,{attributes:true,subtree:true,attributeFilter:['open']});return ()=>{alive=false;playback?.dispose();disposers.forEach(f=>f());observer.disconnect();window.removeEventListener('scroll',visible,true);window.removeEventListener('resize',visible);document.removeEventListener('visibilitychange',visible);zone.onclick=null;retry.onclick=null;};}